from hypothesis import strategies as st
import math

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    choices = st.one_of(
        st.just(1),
        st.just(5000),
        st.integers(1, 5000),
    )
    p = draw(st.lists(choices, min_size=n, max_size=n))
    if draw(st.booleans()):
        p = sorted(p)
    if draw(st.booleans()):
        p = sorted(p, reverse=True)
    return f"{n}\n{' '.join(map(str, p))}\n"

def validate(inp):
    try:
        lines = inp.strip("\n").split("\n")
        if len(lines) != 2:
            return False
        first = lines[0].split()
        if len(first) != 1:
            return False
        n = int(first[0])
        p = lines[1].split()
        if not (1 <= n <= 5000):
            return False
        if len(p) != n:
            return False
        vals = [int(x) for x in p]
        return all(1 <= v <= 5000 for v in vals)
    except Exception:
        return False

def _rating(q):
    k = len(q)
    num = 0.0
    den = 0.0
    for i in range(1, k + 1):
        w = 0.9 ** (k - i)
        num += w * q[i - 1]
        den += w
    return num / den - 1200.0 / math.sqrt(k)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    p = [int(x) for x in t[1:1 + n]]
    best = None
    for mask in range(1, 1 << n):
        q = [p[i] for i in range(n) if (mask >> i) & 1]
        r = _rating(q)
        if best is None or r > best:
            best = r
    return f"{best:.15f}"

def same(inp, expected, got):
    try:
        e = float(expected)
        g = float(got.strip())
    except Exception:
        return False
    if math.isnan(g) or math.isinf(g):
        return False
    return abs(g - e) <= 1e-6 * max(1.0, abs(e))
